    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the full horizontal or vertical barrier.
    barrier = None
    for r in range(h):
        for color in set(grid[r]):
            if color != bg and sum(x == color for x in grid[r]) >= w - 1:
                barrier = ("h", r, color)
                break
        if barrier:
            break
    if barrier is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            for color in set(vals):
                if color != bg and sum(x == color for x in vals) >= h - 1:
                    barrier = ("v", c, color)
                    break
            if barrier:
